mapper.select:
SELECT c.id,c.snapshot_id,c.commit_sha,c.file_path,c.symbol_name,c.symbol_kind,c.language, c.chunk_type,c.start_line,c.end_line, LEFT(REGEXP_REPLACE(c.content,E'\\s+',' ','g'),260) content_excerpt, c.content_hash,e.model vector_model,e.dimension,e.created_at vectorized_at, CASE WHEN e.chunk_id IS NULL THEN 'MISSING' ELSE 'EMBEDDED' END vector_status FROM repositories r JOIN code_chunks c ON c.repo_id=r.id AND c.snapshot_id=r.current_snapshot_id LEFT JOIN chunk_embeddings e ON e.chunk_id=c.id WHERE r.id=#{repositoryId}
AND( POSITION(LOWER(#{query}) IN LOWER(c.file_path))>0 OR POSITION(LOWER(#{query}) IN LOWER(COALESCE(c.symbol_name,'')))>0 OR POSITION(LOWER(#{query}) IN LOWER(c.content))>0 )
AND e.chunk_id IS NOT NULL AND e.chunk_id IS NULL AND c.chunk_type=#{chunkType} ORDER BY CASE WHEN e.chunk_id IS NULL THEN 0 ELSE 1 END,c.file_path,c.start_line,c.id
